def solve(arr, preserve_pairs=None):
    if preserve_pairs is None:
        preserve_pairs = [(5, 3), (3, 0), (5, 2)]

    n = len(arr)

    # Build constraint graph: edge i -> j means element at original index i must come before j
    adj = {i: [] for i in range(n)}
    in_degree = {i: 0 for i in range(n)}

    for i, j in preserve_pairs:
        if i not in adj or j not in adj:
            raise ValueError(f"Index {i} or {j} out of bounds for array of length {n}")
        adj[i].append(j)
        in_degree[j] += 1

    # Kahn's algorithm for topological sort
    queue = [i for i in range(n) if in_degree[i] == 0]
    result_indices = []

    while queue:
        queue.sort()  # Deterministic order for stability
        u = queue.pop(0)
        result_indices.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result_indices) != n:
        raise ValueError("Cycle detected in constraints; no valid ordering exists.")

    # Extract values in the topological order
    return [arr[i] for i in result_indices]
